function seoTelegramParts(result) {
  const refs = result.sources
    .map((src) => "[" + src.index + "] " + src.title + "\n" + src.url)
    .join("\n");
  let remaining = [
    result.article.title,
    result.article.subtitle,
    result.article.content,
    result.article.hashtags.join(" "),
    "Sources\n" + refs,
  ]
    .filter(Boolean)
    .join("\n\n");
  const pieces = [];
  while (remaining.length > 3600) {
    const prefix = remaining.slice(0, 3600);
    let end = Math.max(prefix.lastIndexOf("\n"), prefix.lastIndexOf(" "));
    if (end < 1000) end = 3600;
    if (/[\uD800-\uDBFF]/.test(remaining[end - 1])) end--;
    pieces.push(remaining.slice(0, end));
    remaining = remaining.slice(end).trimStart();
  }
  if (remaining) pieces.push(remaining);
  return pieces;
}
export default async ({ seo, article, sources, route }, context) => {
  if (!(await context.state.insert(route.key, { status: "pending", messageIds: [] })))
    return { sent: false };
  const parts = seoTelegramParts({ seo, article, sources }),
    messageIds = [];
  for (const [index, text] of parts.entries()) {
    const input = {
      chatId: route.chatId,
      text,
      disableWebPagePreview: true,
      ...(index === 0 ? { replyToMessageId: route.messageId } : {}),
      ...(route.threadId ? { messageThreadId: route.threadId } : {}),
    };
    let response;
    try {
      response = await context.actions.call("telegram.send_message", input);
    } catch {
      throw Error("Telegram did not confirm the article reply. Check the original chat.");
    }
    if (
      String(response?.chat?.id) !== route.chatId ||
      !Number.isSafeInteger(response?.messageId) ||
      response.messageId < 1 ||
      messageIds.includes(response.messageId)
    )
      throw Error("Telegram confirmed an unexpected message.");
    messageIds.push(response.messageId);
    await context.state.set(route.key, { status: "pending", messageIds: [...messageIds] });
  }
  await context.state.set(route.key, { status: "accepted", messageIds });
  return { sent: true };
};
